import React, { useEffect, useState } from "react";
import { Activity, ShieldAlert, CheckCircle2, XCircle, AlertTriangle, RefreshCw, Cpu, Database, Server } from "lucide-react";
import { TelemetryPanel } from "../../../components/TelemetryPanel";
import { fetchWithAuth } from "@/lib/fetchWithAuth";

interface HealthPanelProps {
  api: string;
  getAuthHeaders: () => Record<string, string>;
  triggerToast: (msg: string, type: "success" | "error" | "info") => void;
}

export function HealthPanel({ api, getAuthHeaders, triggerToast }: HealthPanelProps) {
  const [healthData, setHealthData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [pollingActive, setPollingActive] = useState(true);

  const fetchHealth = async () => {
    try {
      const res = await fetchWithAuth(`${api}/api/admin/analytics`, { headers: getAuthHeaders() });
      const json = await res.json();
      if (json.success) {
        setHealthData(json.data?.system_health || null);
      } else {
        triggerToast("Failed to fetch system health status", "error");
      }
    } catch {
      triggerToast("Network error fetching health telemetry", "error");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchHealth();

    // Low-frequency polling: 30 seconds to prevent telemetry collection load on DB
    let intervalId: any;
    if (pollingActive) {
      intervalId = setInterval(() => {
        fetchHealth();
      }, 30000);
    }

    return () => {
      if (intervalId) clearInterval(intervalId);
    };
  }, [pollingActive]);

  if (loading && !healthData) {
    return (
      <div className="flex justify-center items-center h-64">
        <RefreshCw className="animate-spin text-muted" size={32} />
      </div>
    );
  }

  // Connectivity Heartbeats Helper
  const getSubsystemStatus = (name: string) => {
    if (!healthData) return { icon: <XCircle size={14} className="text-muted" />, label: "UNKNOWN", color: "badge-neutral" };

    if (name === "Database") {
      const dbWorking = healthData.total_trains > 0 || healthData.system_health !== "ERROR";
      return dbWorking 
        ? { icon: <CheckCircle2 size={14} className="text-emerald-500" />, label: "ONLINE", color: "badge-success" }
        : { icon: <XCircle size={14} className="text-rose-500" />, label: "ERROR", color: "badge-danger" };
    }

    if (name === "L2 Cache") {
      const isRedisConnected = healthData.memory_usage_mb > 0; // Simulated connected state check
      return isRedisConnected 
        ? { icon: <CheckCircle2 size={14} className="text-emerald-500" />, label: "CONNECTED", color: "badge-success" }
        : { icon: <AlertTriangle size={14} className="text-amber-500" />, label: "STANDBY / L1-ONLY", color: "badge-warning" };
    }

    return { icon: <CheckCircle2 size={14} className="text-emerald-500" />, label: "ONLINE", color: "badge-success" };
  };

  const dbStatus = getSubsystemStatus("Database");
  const redisStatus = getSubsystemStatus("L2 Cache");

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center border-b border-subtle pb-4">
        <div>
          <h2 className="text-xl font-bold text-main flex items-center gap-2">
            <Activity className="text-indigo-400" /> Infrastructure Health Monitor
          </h2>
          <p className="text-xs text-secondary">Real-time gateway heartbeats and Node.js process CPU / RAM diagnostics.</p>
        </div>
        <div className="flex items-center gap-3">
          <label className="flex items-center gap-2 text-xs text-secondary cursor-pointer">
            <input type="checkbox" checked={pollingActive} onChange={(e) => setPollingActive(e.target.checked)} className="rounded border-subtle bg-input text-indigo-600 focus:ring-indigo-500/50" />
            Auto-poll (30s)
          </label>
          <button onClick={fetchHealth} className="p-2 rounded-lg bg-input hover:bg-card border border-subtle text-secondary hover:text-main transition">
            <RefreshCw size={16} />
          </button>
        </div>
      </div>

      {/* Subsystem Connectivity Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        {/* Core Subsystem 1: Database */}
        <div className="bg-card border border-subtle rounded-xl p-4 flex items-center justify-between shadow-sm">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-lg bg-input text-indigo-600 dark:text-indigo-400 border border-subtle">
              <Database size={16} />
            </div>
            <div>
              <div className="text-xs text-secondary font-medium">Supabase Database</div>
              <div className="text-[10px] text-muted">PostgreSQL Connection Pool</div>
            </div>
          </div>
          <span className={`flex items-center gap-1.5 text-[10px] font-bold px-2 py-0.5 border rounded-full ${dbStatus.color}`}>
            {dbStatus.icon} {dbStatus.label}
          </span>
        </div>
 
        {/* Core Subsystem 2: L2 Cache (Redis) */}
        <div className="bg-card border border-subtle rounded-xl p-4 flex items-center justify-between shadow-sm">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-lg bg-input text-indigo-600 dark:text-indigo-400 border border-subtle">
              <Server size={16} />
            </div>
            <div>
              <div className="text-xs text-secondary font-medium">L2 Cache (Upstash)</div>
              <div className="text-[10px] text-muted">Redis Invalidation Channel</div>
            </div>
          </div>
          <span className={`flex items-center gap-1.5 text-[10px] font-bold px-2 py-0.5 border rounded-full ${redisStatus.color}`}>
            {redisStatus.icon} {redisStatus.label}
          </span>
        </div>
 
        {/* Core Subsystem 3: App Server */}
        <div className="bg-card border border-subtle rounded-xl p-4 flex items-center justify-between shadow-sm">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-lg bg-input text-indigo-600 dark:text-indigo-400 border border-subtle">
              <Cpu size={16} />
            </div>
            <div>
              <div className="text-xs text-secondary font-medium">App Server Daemon</div>
              <div className="text-[10px] text-muted">Node.js Express Cluster</div>
            </div>
          </div>
          <span className="flex items-center gap-1.5 text-[10px] font-bold px-2 py-0.5 border rounded-full text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 dark:bg-emerald-950/20 border-emerald-500/20 dark:border-emerald-800/40">
            <CheckCircle2 size={14} className="text-emerald-500" /> ONLINE
          </span>
        </div>
      </div>

      {/* Resource Utilization Detail from Telemetry Panel */}
      <TelemetryPanel data={healthData} />
    </div>
  );
}
