'use client';

import React, { useState, useEffect, useCallback } from 'react';
import {
  ToggleLeft,
  ToggleRight,
  AlertTriangle,
  Flame,
  RotateCcw,
  History,
  Shield,
  Search,
  CheckCircle2,
  XCircle,
  AlertOctagon,
  Eye,
  RefreshCw,
  Zap,
  Lock,
  Layers,
  ArrowRight,
  Sparkles,
  Server,
  Info
} from 'lucide-react';

export type FeatureFlagKey =
  | 'TRAIN_SEARCH_MASTER'
  | 'TRAIN_SEARCH_CACHE_FALLBACK'
  | 'SPLIT_JOURNEY_MASTER'
  | 'SPLIT_JOURNEY_AI_RESCUE'
  | 'AI_PNR_PREDICTION_MASTER'
  | 'AI_ROUTE_ENRICHMENT_MASTER'
  | 'LIVE_TRACKING_MASTER'
  | 'LIVE_TRACKING_RADAR'
  | 'SMART_AVAILABILITY_CACHE'
  | 'AVAILABILITY_MULTI_PROVIDER'
  | 'SMART_RANKING_MASTER'
  | 'TRAIN_RELIABILITY_SCORES'
  | 'USER_FEEDBACK_INTELLIGENCE'
  | 'RAIL_PROVIDER_CIRCUIT_BREAKER'
  | 'BOOKING_GATEWAY_MASTER'
  | 'AI_PROVIDER_ROUTING_MASTER'
  | 'REWARDED_ADS_MASTER'
  | 'ADMIN_BULK_OPERATIONS_MASTER';

export type FeatureFlagCategory =
  | 'CORE_SEARCH'
  | 'SPLIT_ENGINE'
  | 'PNR_PREDICTIONS'
  | 'AI_SERVICES'
  | 'LIVE_TRACKING'
  | 'AVAILABILITY'
  | 'RANKING_SCORING'
  | 'RELIABILITY'
  | 'USER_FEEDBACK'
  | 'EXTERNAL_PROVIDERS'
  | 'BOOKING_GATEWAY'
  | 'AI_PROVIDERS'
  | 'MONETIZATION'
  | 'ADMINISTRATION';

export type FeatureFlagState = 'ENABLED' | 'DISABLED' | 'EMERGENCY_OFF';
export type FeatureFlagRisk = 'LOW' | 'MEDIUM' | 'HIGH';

export interface FeatureFlagDefinition {
  key: FeatureFlagKey;
  name: string;
  category: FeatureFlagCategory;
  riskLevel: FeatureFlagRisk;
  description: string;
  state: FeatureFlagState;
  killSwitchEnabled: boolean;
  updatedAt: string;
  updatedBy: string;
  reason?: string;
  killSwitchActivatedAt?: string;
  killSwitchActivatedBy?: string;
}

export interface FeatureFlagAuditEntry {
  id: string;
  key: FeatureFlagKey;
  action: 'UPDATE' | 'KILL_SWITCH' | 'ROLLBACK';
  previousState: FeatureFlagState;
  newState: FeatureFlagState;
  adminId: string;
  adminEmail: string;
  reason: string;
  timestamp: string;
  snapshot: FeatureFlagDefinition;
}

export interface FeatureImpactPreview {
  key: FeatureFlagKey;
  name: string;
  category: FeatureFlagCategory;
  riskLevel: FeatureFlagRisk;
  currentState: FeatureFlagState;
  targetState: FeatureFlagState;
  isEmergencyKill: boolean;
  warnings: string[];
  affectedSubsystems: string[];
  safeFallbackDescription: string;
  confirmationCode?: string;
}

interface FeatureFlagsPanelProps {
  api: string;
  getAuthHeaders: () => Record<string, string>;
  triggerToast?: (message: string, type?: 'success' | 'error' | 'info') => void;
}

export function FeatureFlagsPanel({ api, getAuthHeaders, triggerToast }: FeatureFlagsPanelProps) {
  const [flags, setFlags] = useState<FeatureFlagDefinition[]>([]);
  const [stats, setStats] = useState({ total: 0, enabled: 0, disabled: 0, emergencyOff: 0, highRisk: 0 });
  const [auditLogs, setAuditLogs] = useState<FeatureFlagAuditEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string>('ALL');

  // Modal States
  const [previewModal, setPreviewModal] = useState<{ open: boolean; preview: FeatureImpactPreview | null }>({
    open: false,
    preview: null
  });
  const [killSwitchModal, setKillSwitchModal] = useState<{ open: boolean; flag: FeatureFlagDefinition | null }>({
    open: false,
    flag: null
  });
  const [rollbackModal, setRollbackModal] = useState<{ open: boolean; flag: FeatureFlagDefinition | null }>({
    open: false,
    flag: null
  });
  const [historyDrawerOpen, setHistoryDrawerOpen] = useState(false);

  // Form Inputs
  const [updateReason, setUpdateReason] = useState('');
  const [killSwitchCodeInput, setKillSwitchCodeInput] = useState('');
  const [killSwitchReasonInput, setKillSwitchReasonInput] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const fetchFlags = useCallback(async () => {
    try {
      setLoading(true);
      const res = await fetch(`${api}/api/admin/feature-flags`, {
        headers: getAuthHeaders()
      });
      const json = await res.json();
      if (json.success && json.data) {
        setFlags(json.data.flags || []);
        setStats(json.data.stats || { total: 0, enabled: 0, disabled: 0, emergencyOff: 0, highRisk: 0 });
      }
    } catch (err: any) {
      triggerToast?.(`Failed to load feature flags: ${err.message}`, 'error');
    } finally {
      setLoading(false);
    }
  }, [api, getAuthHeaders, triggerToast]);

  const fetchAuditLogs = useCallback(async () => {
    try {
      const res = await fetch(`${api}/api/admin/feature-flags/history/logs`, {
        headers: getAuthHeaders()
      });
      const json = await res.json();
      if (json.success && json.data) {
        setAuditLogs(json.data);
      }
    } catch (err: any) {
      console.error('Failed to load audit logs:', err);
    }
  }, [api, getAuthHeaders]);

  useEffect(() => {
    fetchFlags();
    fetchAuditLogs();
  }, [fetchFlags, fetchAuditLogs]);

  // ── Open Preview for Standard Toggle ───────────────────────────────────────
  const handleInitiateToggle = async (flag: FeatureFlagDefinition, targetState: FeatureFlagState) => {
    try {
      setIsSubmitting(true);
      const res = await fetch(`${api}/api/admin/feature-flags/preview`, {
        method: 'POST',
        headers: { ...getAuthHeaders(), 'Content-Type': 'application/json' },
        body: JSON.stringify({ key: flag.key, targetState, isKillSwitch: false })
      });
      const json = await res.json();
      if (json.success && json.data) {
        setUpdateReason('');
        setPreviewModal({ open: true, preview: json.data });
      } else {
        triggerToast?.(json.error || 'Failed to generate preview', 'error');
      }
    } catch (err: any) {
      triggerToast?.(`Error: ${err.message}`, 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  // ── Execute Standard State Update ──────────────────────────────────────────
  const handleConfirmUpdate = async () => {
    if (!previewModal.preview) return;
    const { key, targetState } = previewModal.preview;

    if ((targetState === 'DISABLED' || targetState === 'EMERGENCY_OFF') && !updateReason.trim()) {
      triggerToast?.('A reason is mandatory when disabling a feature', 'error');
      return;
    }

    try {
      setIsSubmitting(true);
      const res = await fetch(`${api}/api/admin/feature-flags/${key}/update`, {
        method: 'POST',
        headers: { ...getAuthHeaders(), 'Content-Type': 'application/json' },
        body: JSON.stringify({ newState: targetState, reason: updateReason.trim() })
      });
      const json = await res.json();
      if (json.success) {
        triggerToast?.(json.message || 'Feature flag updated successfully', 'success');
        setPreviewModal({ open: false, preview: null });
        fetchFlags();
        fetchAuditLogs();
      } else {
        triggerToast?.(json.error || 'Update failed', 'error');
      }
    } catch (err: any) {
      triggerToast?.(`Update error: ${err.message}`, 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  // ── Open Emergency Kill Switch Modal ───────────────────────────────────────
  const handleInitiateKillSwitch = (flag: FeatureFlagDefinition) => {
    setKillSwitchCodeInput('');
    setKillSwitchReasonInput('');
    setKillSwitchModal({ open: true, flag });
  };

  // ── Execute Emergency Kill Switch ──────────────────────────────────────────
  const handleConfirmKillSwitch = async () => {
    if (!killSwitchModal.flag) return;
    const flag = killSwitchModal.flag;
    const expectedCode = `KILL-SWITCH-${flag.key}`;

    if (killSwitchCodeInput.trim() !== expectedCode) {
      triggerToast?.(`Safety code mismatch! Please type exact confirmation code: ${expectedCode}`, 'error');
      return;
    }

    if (!killSwitchReasonInput.trim() || killSwitchReasonInput.trim().length < 5) {
      triggerToast?.('Detailed operational reason (min 5 chars) is mandatory for emergency shutdown.', 'error');
      return;
    }

    try {
      setIsSubmitting(true);
      const res = await fetch(`${api}/api/admin/feature-flags/${flag.key}/kill-switch`, {
        method: 'POST',
        headers: { ...getAuthHeaders(), 'Content-Type': 'application/json' },
        body: JSON.stringify({
          confirmationCode: killSwitchCodeInput.trim(),
          reason: killSwitchReasonInput.trim()
        })
      });
      const json = await res.json();
      if (json.success) {
        triggerToast?.(`🚨 ${json.message}`, 'error');
        setKillSwitchModal({ open: false, flag: null });
        fetchFlags();
        fetchAuditLogs();
      } else {
        triggerToast?.(json.error || 'Kill switch failed', 'error');
      }
    } catch (err: any) {
      triggerToast?.(`Kill switch error: ${err.message}`, 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  // ── Execute Rollback ───────────────────────────────────────────────────────
  const handleConfirmRollback = async () => {
    if (!rollbackModal.flag) return;
    const flag = rollbackModal.flag;

    try {
      setIsSubmitting(true);
      const res = await fetch(`${api}/api/admin/feature-flags/${flag.key}/rollback`, {
        method: 'POST',
        headers: { ...getAuthHeaders(), 'Content-Type': 'application/json' },
        body: JSON.stringify({ confirmation: true })
      });
      const json = await res.json();
      if (json.success) {
        triggerToast?.(json.message || 'Rollback successful', 'success');
        setRollbackModal({ open: false, flag: null });
        fetchFlags();
        fetchAuditLogs();
      } else {
        triggerToast?.(json.error || 'Rollback failed', 'error');
      }
    } catch (err: any) {
      triggerToast?.(`Rollback error: ${err.message}`, 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  // ── Filtered Flags ─────────────────────────────────────────────────────────
  const categories = Array.from(new Set(flags.map(f => f.category)));

  const filteredFlags = flags.filter(f => {
    const matchesSearch =
      f.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      f.key.toLowerCase().includes(searchQuery.toLowerCase()) ||
      f.description.toLowerCase().includes(searchQuery.toLowerCase());

    const matchesCategory = selectedCategory === 'ALL' || f.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className="space-y-6 text-main">
      {/* ── Header & KPI Cards ──────────────────────────────────────────────── */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold tracking-tight flex items-center gap-2.5">
            <Zap className="text-amber-500 dark:text-amber-400" size={24} />
            Feature Flags &amp; Kill Switches
          </h2>
          <p className="text-sm text-muted mt-0.5">
            Safe runtime feature controls, zero-restart toggling, emergency kill switches, and instant rollback.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setHistoryDrawerOpen(true)}
            className="flex items-center gap-2 px-3 py-2 text-xs font-semibold rounded-lg bg-surface border border-subtle hover:border-strong text-main transition-all shadow-sm"
          >
            <History size={14} />
            Audit Trail ({auditLogs.length})
          </button>
          <button
            onClick={() => { fetchFlags(); fetchAuditLogs(); }}
            disabled={loading}
            className="flex items-center gap-2 px-3 py-2 text-xs font-bold rounded-lg bg-primary text-white hover:opacity-90 transition-all shadow-sm"
          >
            <RefreshCw size={14} className={loading ? 'animate-spin' : ''} />
            Sync Status
          </button>
        </div>
      </div>

      {/* ── KPI Grid ────────────────────────────────────────────────────────── */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-3.5">
        <div className="bg-card p-4 rounded-xl border border-subtle shadow-sm">
          <div className="text-xs font-semibold text-muted">Total Feature Flags</div>
          <div className="text-2xl font-bold mt-1 text-main">{stats.total}</div>
          <div className="text-[11px] text-muted mt-0.5">Registered canonical</div>
        </div>
        <div className="bg-card p-4 rounded-xl border border-subtle shadow-sm">
          <div className="text-xs font-semibold text-emerald-600 dark:text-emerald-400">Active (ENABLED)</div>
          <div className="text-2xl font-bold mt-1 text-emerald-600 dark:text-emerald-400">{stats.enabled}</div>
          <div className="text-[11px] text-muted mt-0.5">Full operational traffic</div>
        </div>
        <div className="bg-card p-4 rounded-xl border border-subtle shadow-sm">
          <div className="text-xs font-semibold text-amber-600 dark:text-amber-400">Inactive (DISABLED)</div>
          <div className="text-2xl font-bold mt-1 text-amber-600 dark:text-amber-400">{stats.disabled}</div>
          <div className="text-[11px] text-muted mt-0.5">Safe fallback mode</div>
        </div>
        <div className="bg-card p-4 rounded-xl border border-rose-300 dark:border-rose-900/50 bg-rose-50/70 dark:bg-rose-950/10 shadow-sm">
          <div className="text-xs font-bold text-rose-600 dark:text-rose-400 flex items-center gap-1.5">
            <Flame size={13} /> Emergency Off
          </div>
          <div className="text-2xl font-bold mt-1 text-rose-600 dark:text-rose-400">{stats.emergencyOff}</div>
          <div className="text-[11px] text-rose-700 dark:text-rose-400/80 mt-0.5">Kill switches active</div>
        </div>
        <div className="bg-card p-4 rounded-xl border border-subtle shadow-sm">
          <div className="text-xs font-semibold text-indigo-600 dark:text-indigo-400">High Risk Subsystems</div>
          <div className="text-2xl font-bold mt-1 text-indigo-600 dark:text-indigo-400">{stats.highRisk}</div>
          <div className="text-[11px] text-muted mt-0.5">Protected with kill switch</div>
        </div>
      </div>

      {/* ── Search & Filters ────────────────────────────────────────────────── */}
      <div className="flex flex-col md:flex-row gap-3 items-center justify-between bg-card p-3 rounded-xl border border-subtle">
        <div className="relative w-full md:w-80">
          <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted" />
          <input
            type="text"
            placeholder="Search flag name, key, or category..."
            value={searchQuery}
            onChange={e => setSearchQuery(e.target.value)}
            className="w-full pl-9 pr-3 py-1.5 text-xs bg-surface border border-subtle rounded-lg text-main placeholder:text-muted focus:outline-none focus:border-strong shadow-sm"
          />
        </div>
        <div className="flex items-center gap-1.5 overflow-x-auto w-full md:w-auto pb-1 md:pb-0">
          <button
            onClick={() => setSelectedCategory('ALL')}
            className={`px-2.5 py-1 text-xs font-medium rounded-lg whitespace-nowrap transition-all ${
              selectedCategory === 'ALL'
                ? 'bg-primary text-white font-bold shadow-sm'
                : 'bg-surface text-secondary hover:text-main border border-subtle'
            }`}
          >
            All Categories ({flags.length})
          </button>
          {categories.map(cat => (
            <button
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              className={`px-2.5 py-1 text-xs font-medium rounded-lg whitespace-nowrap transition-all ${
                selectedCategory === cat
                  ? 'bg-primary text-white font-bold shadow-sm'
                  : 'bg-surface text-secondary hover:text-main border border-subtle'
              }`}
            >
              {cat} ({flags.filter(f => f.category === cat).length})
            </button>
          ))}
        </div>
      </div>

      {/* ── Feature Flag Cards Grid ─────────────────────────────────────────── */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredFlags.map(flag => {
          const isEnabled = flag.state === 'ENABLED';
          const isEmergency = flag.state === 'EMERGENCY_OFF';

          return (
            <div
              key={flag.key}
              className={`p-4 rounded-xl border flex flex-col justify-between transition-all bg-card ${
                isEmergency
                  ? 'border-rose-500/70 bg-rose-50/50 dark:bg-rose-950/15 shadow-[0_0_15px_rgba(225,29,72,0.15)]'
                  : isEnabled
                  ? 'border-subtle hover:border-strong'
                  : 'border-subtle/80 bg-surface/30 opacity-90'
              }`}
            >
              <div>
                {/* Badges Bar */}
                <div className="flex items-center justify-between gap-2 mb-2">
                  <div className="flex items-center gap-1.5 flex-wrap">
                    <span className="text-[10px] font-mono px-2 py-0.5 rounded-md badge-neutral">
                      {flag.category}
                    </span>
                    <span
                      className={`text-[10px] font-bold px-2 py-0.5 rounded-md ${
                        flag.riskLevel === 'HIGH'
                          ? 'badge-danger'
                          : flag.riskLevel === 'MEDIUM'
                          ? 'badge-warning'
                          : 'badge-success'
                      }`}
                    >
                      {flag.riskLevel} RISK
                    </span>
                  </div>

                  {/* State Pill */}
                  <div
                    className={`flex items-center gap-1.5 text-[11px] font-bold px-2.5 py-0.5 rounded-full ${
                      isEmergency
                        ? 'badge-danger animate-pulse'
                        : isEnabled
                        ? 'badge-success'
                        : 'badge-warning'
                    }`}
                  >
                    <span
                      className={`w-1.5 h-1.5 rounded-full ${
                        isEmergency ? 'bg-rose-500' : isEnabled ? 'bg-emerald-500' : 'bg-amber-500'
                      }`}
                    />
                    {flag.state}
                  </div>
                </div>

                {/* Title & Key */}
                <h3 className="font-bold text-sm text-main flex items-center gap-1.5">
                  {flag.name}
                </h3>
                <div className="text-[11px] font-mono text-muted mt-0.5 select-all">
                  {flag.key}
                </div>

                {/* Description */}
                <p className="text-xs text-secondary mt-2 leading-relaxed line-clamp-2">
                  {flag.description}
                </p>

                {/* Reason & Emergency Meta */}
                {flag.reason && (
                  <div className="mt-2.5 p-2 rounded-lg bg-surface border border-subtle text-[11px] text-muted">
                    <span className="font-bold text-main">Note: </span>
                    {flag.reason}
                  </div>
                )}

                {isEmergency && flag.killSwitchActivatedBy && (
                  <div className="mt-2 text-[11px] text-rose-600 dark:text-rose-400 font-bold flex items-center gap-1">
                    <AlertTriangle size={12} />
                    Killed by {flag.killSwitchActivatedBy} on {new Date(flag.killSwitchActivatedAt || '').toLocaleTimeString()}
                  </div>
                )}
              </div>

              {/* Action Controls Footer */}
              <div className="mt-4 pt-3 border-t border-subtle flex items-center justify-between gap-2">
                <div className="flex items-center gap-1">
                  {/* Standard Toggle */}
                  <button
                    onClick={() => handleInitiateToggle(flag, isEnabled ? 'DISABLED' : 'ENABLED')}
                    className={`flex items-center gap-1 px-2.5 py-1 text-xs font-bold rounded-lg border transition-all ${
                      isEnabled
                        ? 'badge-success hover:opacity-90'
                        : 'badge-neutral hover:bg-surface'
                    }`}
                  >
                    {isEnabled ? <ToggleRight size={14} className="text-emerald-600 dark:text-emerald-400" /> : <ToggleLeft size={14} />}
                    {isEnabled ? 'Enabled' : 'Disabled'}
                  </button>

                  {/* Rollback Button */}
                  <button
                    onClick={() => setRollbackModal({ open: true, flag })}
                    title="Rollback to previous state"
                    className="p-1.5 rounded-lg bg-surface border border-subtle hover:border-strong text-secondary hover:text-main transition-all shadow-sm"
                  >
                    <RotateCcw size={13} />
                  </button>
                </div>

                {/* Emergency Kill Switch Button */}
                {flag.killSwitchEnabled && (
                  <button
                    onClick={() => handleInitiateKillSwitch(flag)}
                    className={`flex items-center gap-1 px-2.5 py-1 text-xs font-bold rounded-lg transition-all ${
                      isEmergency
                        ? 'bg-rose-100 dark:bg-rose-900/40 text-rose-800 dark:text-rose-300 border border-rose-300 dark:border-rose-700/60 hover:opacity-90'
                        : 'bg-rose-50 dark:bg-rose-950/50 text-rose-700 dark:text-rose-400 border border-rose-200 dark:border-rose-900 hover:bg-rose-100 dark:hover:bg-rose-900/40'
                    }`}
                  >
                    <Flame size={13} className="text-rose-500" />
                    Kill Switch
                  </button>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {filteredFlags.length === 0 && (
        <div className="text-center py-12 bg-card rounded-xl border border-subtle shadow-sm">
          <AlertOctagon size={32} className="mx-auto text-muted mb-2" />
          <div className="text-sm font-bold text-main">No feature flags found</div>
          <div className="text-xs text-muted mt-1">Try adjusting your search query or selected category.</div>
        </div>
      )}

      {/* ── Impact Preview & Confirmation Modal ───────────────────────────────── */}
      {previewModal.open && previewModal.preview && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
          <div className="bg-card w-full max-w-lg rounded-2xl border border-subtle p-6 shadow-2xl space-y-4 animate-in fade-in-50 zoom-in-95 duration-150 text-main">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Shield size={18} className="text-primary" />
                <h3 className="font-bold text-base text-main">Impact Preview: {previewModal.preview.name}</h3>
              </div>
              <button
                onClick={() => setPreviewModal({ open: false, preview: null })}
                className="text-muted hover:text-main text-xs font-bold"
              >
                ✕
              </button>
            </div>

            {/* State Transition Diff */}
            <div className="flex items-center justify-between p-3 rounded-xl bg-surface border border-subtle">
              <div className="text-center">
                <div className="text-[10px] text-muted uppercase font-bold">Current</div>
                <div className="text-xs font-bold text-main mt-0.5">{previewModal.preview.currentState}</div>
              </div>
              <ArrowRight size={16} className="text-muted" />
              <div className="text-center">
                <div className="text-[10px] text-muted uppercase font-bold">Target</div>
                <div
                  className={`text-xs font-bold mt-0.5 ${
                    previewModal.preview.targetState === 'ENABLED'
                      ? 'text-emerald-600 dark:text-emerald-400'
                      : previewModal.preview.targetState === 'EMERGENCY_OFF'
                      ? 'text-rose-600 dark:text-rose-400'
                      : 'text-amber-600 dark:text-amber-400'
                  }`}
                >
                  {previewModal.preview.targetState}
                </div>
              </div>
            </div>

            {/* Warnings */}
            {previewModal.preview.warnings.length > 0 && (
              <div className="p-3 rounded-xl bg-amber-50 dark:bg-amber-950/20 border border-amber-200 dark:border-amber-900/50 space-y-1.5">
                <div className="text-xs font-bold text-amber-800 dark:text-amber-400 flex items-center gap-1.5">
                  <AlertTriangle size={13} /> Side-effect &amp; Traffic Impact Warnings:
                </div>
                <ul className="text-xs text-amber-900 dark:text-amber-300/90 list-disc list-inside space-y-0.5">
                  {previewModal.preview.warnings.map((w, idx) => (
                    <li key={idx}>{w}</li>
                  ))}
                </ul>
              </div>
            )}

            {/* Affected Subsystems */}
            <div className="space-y-1">
              <div className="text-xs font-bold text-main">Affected Endpoints / Subsystems:</div>
              <div className="flex flex-wrap gap-1.5">
                {previewModal.preview.affectedSubsystems.map((sub, i) => (
                  <span key={i} className="text-[11px] px-2 py-0.5 rounded-md badge-neutral font-mono">
                    {sub}
                  </span>
                ))}
              </div>
            </div>

            {/* Safe Fallback Strategy */}
            <div className="p-3 rounded-xl bg-surface border border-subtle text-xs text-secondary">
              <span className="font-bold text-main">Safe Fallback Behavior: </span>
              {previewModal.preview.safeFallbackDescription}
            </div>

            {/* Reason Field */}
            <div>
              <label className="text-xs font-bold text-main block mb-1">
                Operational Reason {(previewModal.preview.targetState !== 'ENABLED') && <span className="text-rose-500">*</span>}
              </label>
              <textarea
                rows={2}
                placeholder="Describe reason for state modification..."
                value={updateReason}
                onChange={e => setUpdateReason(e.target.value)}
                className="w-full p-2 text-xs bg-surface border border-subtle rounded-lg text-main focus:outline-none focus:border-strong shadow-sm"
              />
            </div>

            {/* Modal Actions */}
            <div className="flex items-center justify-end gap-2 pt-2 border-t border-subtle">
              <button
                onClick={() => setPreviewModal({ open: false, preview: null })}
                disabled={isSubmitting}
                className="px-3 py-1.5 text-xs font-semibold rounded-lg bg-surface border border-subtle text-secondary hover:text-main shadow-sm"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirmUpdate}
                disabled={isSubmitting}
                className="px-4 py-1.5 text-xs font-bold rounded-lg bg-primary text-white hover:opacity-90 flex items-center gap-1.5 shadow-sm"
              >
                {isSubmitting && <RefreshCw size={13} className="animate-spin" />}
                Confirm &amp; Apply Change
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ── Emergency Kill Switch Modal ───────────────────────────────────────── */}
      {killSwitchModal.open && killSwitchModal.flag && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-4">
          <div className="bg-card w-full max-w-lg rounded-2xl border-2 border-rose-600 p-6 shadow-[0_0_50px_rgba(225,29,72,0.3)] space-y-4 animate-in fade-in-50 zoom-in-95 duration-150 text-main">
            <div className="flex items-center justify-between border-b border-rose-200 dark:border-rose-900/50 pb-3">
              <div className="flex items-center gap-2 text-rose-600 dark:text-rose-400">
                <Flame size={22} className="animate-bounce" />
                <h3 className="font-bold text-base">EMERGENCY KILL SWITCH</h3>
              </div>
              <button
                onClick={() => setKillSwitchModal({ open: false, flag: null })}
                className="text-muted hover:text-main text-xs font-bold"
              >
                ✕
              </button>
            </div>

            <div className="p-3 rounded-xl bg-rose-50 dark:bg-rose-950/40 border border-rose-200 dark:border-rose-800 text-xs text-rose-900 dark:text-rose-200 space-y-1">
              <div className="font-bold text-rose-600 dark:text-rose-400">WARNING: IMMEDIATE CIRCUIT CUT</div>
              <p>
                Engaging this kill switch will immediately cut all incoming execution traffic to{' '}
                <strong className="font-bold text-main">{killSwitchModal.flag.name}</strong> ({killSwitchModal.flag.key}).
              </p>
            </div>

            <div>
              <label className="text-xs font-bold text-main block mb-1">
                Type Confirmation Safety Code:
              </label>
              <div className="text-[11px] font-mono text-amber-600 dark:text-amber-400 font-bold select-all mb-1.5">
                KILL-SWITCH-{killSwitchModal.flag.key}
              </div>
              <input
                type="text"
                placeholder={`Type exact code: KILL-SWITCH-${killSwitchModal.flag.key}`}
                value={killSwitchCodeInput}
                onChange={e => setKillSwitchCodeInput(e.target.value)}
                className="w-full p-2 text-xs font-mono bg-surface border border-rose-300 dark:border-rose-800/80 rounded-lg text-main focus:outline-none focus:border-rose-500 shadow-sm"
              />
            </div>

            <div>
              <label className="text-xs font-bold text-main block mb-1">
                Incident Reason (Mandatory, min 5 chars): <span className="text-rose-500">*</span>
              </label>
              <textarea
                rows={2}
                placeholder="Why is this emergency kill switch being triggered? (e.g. Upstream API outage, runaway billing, error spike)..."
                value={killSwitchReasonInput}
                onChange={e => setKillSwitchReasonInput(e.target.value)}
                className="w-full p-2 text-xs bg-surface border border-subtle rounded-lg text-main focus:outline-none focus:border-strong shadow-sm"
              />
            </div>

            <div className="flex items-center justify-end gap-2 pt-2 border-t border-subtle">
              <button
                onClick={() => setKillSwitchModal({ open: false, flag: null })}
                disabled={isSubmitting}
                className="px-3 py-1.5 text-xs font-semibold rounded-lg bg-surface border border-subtle text-secondary hover:text-main shadow-sm"
              >
                Abort
              </button>
              <button
                onClick={handleConfirmKillSwitch}
                disabled={isSubmitting}
                className="px-4 py-1.5 text-xs font-bold rounded-lg bg-rose-600 text-white hover:bg-rose-700 flex items-center gap-1.5 shadow-lg shadow-rose-900/50"
              >
                {isSubmitting && <RefreshCw size={13} className="animate-spin" />}
                ENGAGE EMERGENCY SHUTDOWN
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ── Rollback Modal ───────────────────────────────────────────────────── */}
      {rollbackModal.open && rollbackModal.flag && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
          <div className="bg-card w-full max-w-md rounded-2xl border border-subtle p-6 shadow-2xl space-y-4 animate-in fade-in-50 zoom-in-95 duration-150 text-main">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <RotateCcw size={18} className="text-amber-500" />
                <h3 className="font-bold text-base text-main">Confirm Rollback</h3>
              </div>
              <button
                onClick={() => setRollbackModal({ open: false, flag: null })}
                className="text-muted hover:text-main text-xs font-bold"
              >
                ✕
              </button>
            </div>

            <p className="text-xs text-secondary leading-relaxed">
              Are you sure you want to revert <strong className="text-main font-bold">{rollbackModal.flag.name}</strong> to its previous snapshot? This action will overwrite the current state and emit an audit event.
            </p>

            <div className="p-3 rounded-xl bg-surface border border-subtle text-xs space-y-1">
              <div className="flex justify-between text-muted">
                <span>Current State:</span>
                <span className="font-bold text-main">{rollbackModal.flag.state}</span>
              </div>
              <div className="flex justify-between text-muted">
                <span>Last Updated:</span>
                <span>{new Date(rollbackModal.flag.updatedAt).toLocaleString()}</span>
              </div>
            </div>

            <div className="flex items-center justify-end gap-2 pt-2 border-t border-subtle">
              <button
                onClick={() => setRollbackModal({ open: false, flag: null })}
                disabled={isSubmitting}
                className="px-3 py-1.5 text-xs font-semibold rounded-lg bg-surface border border-subtle text-secondary hover:text-main shadow-sm"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirmRollback}
                disabled={isSubmitting}
                className="px-4 py-1.5 text-xs font-bold rounded-lg bg-amber-500 text-black hover:bg-amber-400 flex items-center gap-1.5 shadow-sm"
              >
                {isSubmitting && <RefreshCw size={13} className="animate-spin" />}
                Confirm Rollback
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ── Audit Trail / History Drawer ─────────────────────────────────────── */}
      {historyDrawerOpen && (
        <div className="fixed inset-0 z-50 flex justify-end bg-black/60 backdrop-blur-sm">
          <div className="w-full max-w-lg bg-card h-full border-l border-subtle p-6 flex flex-col justify-between shadow-2xl animate-in slide-in-from-right duration-200 text-main">
            <div>
              <div className="flex items-center justify-between border-b border-subtle pb-3 mb-4">
                <div className="flex items-center gap-2">
                  <History size={18} className="text-primary" />
                  <h3 className="font-bold text-base text-main">Feature Flag Audit Trail</h3>
                </div>
                <button
                  onClick={() => setHistoryDrawerOpen(false)}
                  className="text-muted hover:text-main text-xs font-bold"
                >
                  ✕ Close
                </button>
              </div>

              <div className="space-y-3 overflow-y-auto max-h-[calc(100vh-140px)] pr-1">
                {auditLogs.map(log => (
                  <div key={log.id} className="p-3 rounded-xl bg-surface border border-subtle space-y-1.5 text-xs">
                    <div className="flex items-center justify-between gap-2">
                      <span className="font-mono text-[11px] font-bold text-main">{log.key}</span>
                      <span
                        className={`px-2 py-0.5 rounded text-[10px] font-bold ${
                          log.action === 'KILL_SWITCH'
                            ? 'badge-danger'
                            : log.action === 'ROLLBACK'
                            ? 'badge-warning'
                            : 'badge-success'
                        }`}
                      >
                        {log.action}
                      </span>
                    </div>

                    <div className="flex items-center gap-2 text-muted text-[11px]">
                      <span>{log.previousState}</span>
                      <ArrowRight size={12} />
                      <span className="font-bold text-main">{log.newState}</span>
                    </div>

                    <p className="text-[11px] text-secondary italic">"{log.reason}"</p>

                    <div className="flex items-center justify-between text-[10px] text-muted pt-1 border-t border-subtle font-mono">
                      <span>{log.adminEmail}</span>
                      <span>{new Date(log.timestamp).toLocaleString()}</span>
                    </div>
                  </div>
                ))}

                {auditLogs.length === 0 && (
                  <div className="text-center py-12 text-muted text-xs">No audit events recorded yet.</div>
                )}
              </div>
            </div>

            <div className="pt-3 border-t border-subtle">
              <button
                onClick={() => setHistoryDrawerOpen(false)}
                className="w-full py-2 text-xs font-bold rounded-lg bg-surface border border-subtle text-main hover:bg-card shadow-sm"
              >
                Close Drawer
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
