"use client";

import React, { useEffect, useState, useCallback } from "react";
import { useRouter } from "next/navigation";
import {
  ShieldAlert, Users, Activity, Banknote, Shield, Cpu,
  Lock, RefreshCw, X, Loader2, LogOut, BarChart3, Radio, AlertTriangle, MessageSquare, Megaphone, Flame, Sparkles, Layers, Zap, Map, ArrowRight, Newspaper
} from "lucide-react";

import Link from "next/link";
import { fetchWithAuth } from "@/lib/fetchWithAuth";
import { API_HOST } from "@/lib/api";

import { AnalyticsPanel } from "./components/AnalyticsPanel";
import { UsersPanel } from "./components/UsersPanel";
import { ProvidersPanel } from "./components/ProvidersPanel";
import { RatesPanel } from "./components/RatesPanel";
import { AuditLogsPanel } from "./components/AuditLogsPanel";
import { HealthPanel } from "./components/HealthPanel";
import { OperationsPanel } from "./components/OperationsPanel";
import { FeedbackReviewPanel } from "./components/FeedbackReviewPanel";
import { DailyAiPanel } from "./components/DailyAiPanel";
import { IncidentCenterPanel } from "./components/IncidentCenterPanel";
import { IntelligenceV2Panel } from "./components/IntelligenceV2Panel";
import { ProductionIncidentsPanel } from "./components/ProductionIncidentsPanel";
import { BulkOperationsPanel } from "./components/BulkOperationsPanel";
import { FeatureFlagsPanel } from "./components/FeatureFlagsPanel";
import { SignupIntelligencePanel } from "./components/SignupIntelligencePanel";
import { LearningIntelligencePanel } from "./components/LearningIntelligencePanel";
import { NewsControlCenterPanel } from "./components/NewsControlCenterPanel";
import { NewsAnalyticsPanel } from "./components/NewsAnalyticsPanel";
import { WhatsAppCrmPanel } from "./components/WhatsAppCrmPanel";
import { AdminLivePulseTicker } from "./components/AdminLivePulseTicker";
import { RevenuePanel } from "./components/RevenuePanel";
import { OffersPopupPanel } from "./components/OffersPopupPanel";
import { BroadcastCenterPanel } from "./components/BroadcastCenterPanel";
import { SearchDemandPanel } from "./components/SearchDemandPanel";
import { PnrIntelligencePanel } from "./components/PnrIntelligencePanel";
import { MobileVerificationPanel } from "./components/MobileVerificationPanel";
import { UserCheck, Brain, Sun, Moon, TrendingUp, BadgePercent, Globe, Ticket, Smartphone } from "lucide-react";

const API = API_HOST;

// PHASE_4C986: getAuthHeaders is kept for panel components that receive it as a prop.
// The race-condition fix is in verifyAdminAuth() — ensureAccessToken() is called there
// before any API request, guaranteeing the token is in localStorage.
function getAuthHeaders(): Record<string, string> {
  try {
    const token = localStorage.getItem('accessToken') || '';
    return token ? { Authorization: `Bearer ${token}` } : {};
  } catch {
    return {};
  }
}

type TabKey = 
  | "analytics" 
  | "revenue" 
  | "broadcast"
  | "offers-popup" 
  | "search-demand" 
  | "pnr-intel" 
  | "signup-intel" 
  | "mobile-verification"
  | "learning-intel" 
  | "self-learning" 
  | "daily-ai" 
  | "incidents" 
  | "intelligence-v2" 
  | "production-incidents" 
  | "bulk-ops" 
  | "feature-flags" 
  | "users" 
  | "providers" 
  | "rates" 
  | "audit" 
  | "health" 
  | "operations" 
  | "feedback" 
  | "content" 
  | "news" 
  | "news-analytics"
  | "whatsapp";





// ─── Toast ────────────────────────────────────────────────────────────────────
function Toast({ message, type, onClose }: { message: string; type: "success" | "error" | "info"; onClose: () => void }) {
  const icons = {
    success: <Activity size={16} className="text-success" />,
    error: <ShieldAlert size={16} className="text-danger" />,
    info: <Activity size={16} className="text-primary" />
  };
  const borders = {
    success: "border-success/30",
    error: "border-danger/30",
    info: "border-primary/30"
  };
  return (
    <div className={`fixed top-4 right-4 z-50 flex items-center gap-3 bg-card border ${borders[type]} rounded-xl px-4 py-3 shadow-2xl animate-slide-in`}>
      {icons[type]}
      <span className="text-sm text-main font-medium">{message}</span>
      <button onClick={onClose} className="ml-2 text-muted hover:text-main"><X size={14} /></button>
    </div>
  );
}

export default function AdminDashboard() {
  const [analyticsData, setAnalyticsData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [isAdmin, setIsAdmin] = useState<boolean | null>(null);
  const [activeTab, setActiveTab] = useState<TabKey>("analytics");
  const [toast, setToast] = useState<{ message: string; type: "success" | "error" | "info" } | null>(null);
  const [redirectCountdown, setRedirectCountdown] = useState(3);
  const [theme, setTheme] = useState<'light' | 'dark'>('dark');
  
  const router = useRouter();

  useEffect(() => {
    try {
      const saved = localStorage.getItem('theme');
      const isDark = saved ? saved === 'dark' : document.documentElement.classList.contains('dark');
      setTheme(isDark ? 'dark' : 'light');
      if (isDark) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    } catch {}
  }, []);

  const toggleTheme = () => {
    const next = theme === 'dark' ? 'light' : 'dark';
    setTheme(next);
    try {
      localStorage.setItem('theme', next);
    } catch {}
    if (next === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  };

  const showToast = useCallback((message: string, type: "success" | "error" | "info" = "info") => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 4000);
  }, []);

  const verifyAdminAuth = useCallback(async () => {
    try {
      const userStr = localStorage.getItem("user");
      if (!userStr) {
        setIsAdmin(false);
        return;
      }
      let parsedUser: any = null;
      try {
        parsedUser = JSON.parse(userStr);
      } catch {}

      // PHASE_4C986 FIX: Guarantee accessToken is in localStorage before the request.
      const { ensureAccessToken } = await import('@/lib/sessionBootstrap');
      await ensureAccessToken();

      const res = await fetchWithAuth(`${API}/api/admin/analytics`, { headers: getAuthHeaders() as any });

      if (res.status === 403) {
        try {
          const errData = await res.json();
          if (errData?.error === 'account_blocked') {
            localStorage.removeItem('user');
            localStorage.removeItem('accessToken');
            router.push('/login?blocked=true');
            return;
          }
        } catch {}
        setIsAdmin(false);
        return;
      }

      if (res.status === 401) {
        // Attempt silent recovery retry
        const recoveredToken = await ensureAccessToken();
        if (recoveredToken) {
          const retryRes = await fetchWithAuth(`${API}/api/admin/analytics`, { headers: { Authorization: `Bearer ${recoveredToken}` } as any });
          if (retryRes.ok) {
            const json = await retryRes.json();
            if (json.success) {
              setAnalyticsData(json.data);
              setIsAdmin(true);
              return;
            }
          }
        }
        // If known admin in localStorage, do not kick them out on a transient refresh cycle
        if (parsedUser?.isAdmin || parsedUser?.role === 'admin') {
          setIsAdmin(true);
        } else {
          setIsAdmin(false);
        }
        return;
      }

      const json = await res.json();
      if (json.success) {
        setAnalyticsData(json.data);
        setIsAdmin(true);
      } else {
        if (parsedUser?.isAdmin || parsedUser?.role === 'admin') {
          setIsAdmin(true);
        } else {
          setIsAdmin(false);
        }
      }
    } catch {
      // On network failure or unhandled exception, do NOT kick known admin to home screen
      const userStr = localStorage.getItem("user");
      if (userStr) {
        try {
          const u = JSON.parse(userStr);
          if (u.isAdmin || u.role === 'admin') {
            setIsAdmin(true);
            return;
          }
        } catch {}
      }
      setIsAdmin(false);
    } finally {
      setLoading(false);
    }
  }, [router]);

  useEffect(() => {
    verifyAdminAuth();
  }, [verifyAdminAuth]);

  // Access Denied countdown redirect
  useEffect(() => {
    if (isAdmin === false) {
      const interval = setInterval(() => {
        setRedirectCountdown((prev) => {
          if (prev <= 1) {
            clearInterval(interval);
            router.push("/");
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
      return () => clearInterval(interval);
    }
  }, [isAdmin, router]);

  if (loading) {
    return (
      <div className="min-h-screen bg-app flex items-center justify-center">
        <Loader2 size={36} className="animate-spin text-primary" />
      </div>
    );
  }

  // Access Denied Screen (WOW Premium Aesthetics)
  if (isAdmin === false) {
    return (
      <div className="min-h-screen bg-app flex flex-col items-center justify-center text-danger font-sans p-6 select-none relative overflow-hidden">
        {/* glowing background gradients */}
        <div className="absolute top-1/4 left-1/2 -translate-x-1/2 -translate-y-1/2 w-96 h-96 bg-danger/10 rounded-full blur-[100px] pointer-events-none" />
        <div className="absolute bottom-1/4 left-1/2 -translate-x-1/2 translate-y-1/2 w-80 h-80 bg-primary/10 rounded-full blur-[80px] pointer-events-none" />

        <div className="bg-card border border-danger/20 backdrop-blur-md rounded-2xl p-8 max-w-md w-full shadow-2xl flex flex-col items-center text-center space-y-5 animate-fade-in relative">
          <div className="p-4 bg-danger/20 border border-danger/30 rounded-full text-danger shadow-md">
            <Lock size={48} className="animate-pulse" />
          </div>
          <div className="space-y-2">
            <h1 className="text-2xl font-black tracking-wider text-main uppercase">Access Denied</h1>
            <p className="text-xs text-muted leading-relaxed max-w-sm">
              This terminal is locked under administrative governance policies. Standard passenger accounts are barred from command mutations.
            </p>
          </div>

          <div className="text-xs font-semibold px-3 py-1 bg-danger/10 border border-danger/20 rounded-full text-danger">
            Redirecting to home station in {redirectCountdown}s…
          </div>

          <button onClick={() => router.push("/")} className="w-full py-2 bg-input hover:bg-card text-secondary border border-subtle rounded-lg text-xs font-bold transition">
            Return Home Immediately
          </button>
        </div>
      </div>
    );
  }

  const tabs = [
    { key: "analytics", label: "Analytics", icon: <BarChart3 size={14} /> },
    { key: "revenue", label: "Revenue & Plans", icon: <Banknote size={14} className="text-emerald-400" /> },
    { key: "broadcast", label: "Broadcast Center", icon: <Megaphone size={14} className="text-amber-400" /> },
    { key: "offers-popup", label: "Popups & Deals", icon: <BadgePercent size={14} className="text-amber-400" /> },
    { key: "search-demand", label: "Search Demand", icon: <Globe size={14} className="text-cyan-400" /> },
    { key: "pnr-intel", label: "PNR Watchlist", icon: <Ticket size={14} className="text-rose-400" /> },
    { key: "signup-intel", label: "Signup Intel", icon: <UserCheck size={14} /> },
    { key: "mobile-verification", label: "Mobile Verification", icon: <Smartphone size={14} className="text-emerald-400" /> },
    { key: "learning-intel", label: "Learning Observatory", icon: <Brain size={14} /> },
    { key: "self-learning", label: "Missing Routes", icon: <Map size={14} /> },
    { key: "daily-ai", label: "Daily AI", icon: <Cpu size={14} /> },
    { key: "incidents", label: "Incident Center", icon: <Flame size={14} /> },
    { key: "intelligence-v2", label: "Intelligence V2", icon: <Sparkles size={14} /> },
    { key: "production-incidents", label: "Production Incidents", icon: <Flame size={14} /> },
    { key: "bulk-ops", label: "Bulk Operations", icon: <Layers size={14} /> },
    { key: "feature-flags", label: "Feature Flags", icon: <Zap size={14} /> },
    { key: "users", label: "Users", icon: <Users size={14} /> },
    { key: "providers", label: "Providers", icon: <Radio size={14} /> },
    { key: "rates", label: "Rate Cards", icon: <Banknote size={14} /> },
    { key: "audit", label: "Audit Logs", icon: <Shield size={14} /> },
    { key: "health", label: "Health", icon: <Activity size={14} /> },
    { key: "operations", label: "Operations", icon: <Cpu size={14} /> },
    { key: "feedback", label: "Feedback", icon: <MessageSquare size={14} /> },
    { key: "content", label: "Content", icon: <Megaphone size={14} /> },
    { key: "news", label: "News CMS", icon: <Newspaper size={14} /> },
    { key: "news-analytics", label: "News Analytics", icon: <TrendingUp size={14} /> },
    { key: "whatsapp", label: "WhatsApp CRM", icon: <MessageSquare size={14} className="text-emerald-400" /> },
  ] as const;

  return (
    <div className="min-h-screen bg-app text-main font-sans antialiased">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      {/* Header */}
      <div className="sticky top-0 z-40 bg-card/85 backdrop-blur-md border-b border-subtle">
        <div className="max-w-7xl mx-auto px-4 md:px-8 py-4 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <ShieldAlert className="text-indigo-400" size={24} />
            <div>
              <h1 className="text-lg font-bold leading-tight tracking-tight">System Command Center</h1>
              <p className="text-muted text-[10px] uppercase font-bold tracking-wider">Admin Control Board</p>
            </div>
          </div>
          <div className="flex items-center gap-2.5">
            <button
              onClick={toggleTheme}
              aria-label={`Switch to ${theme === 'dark' ? 'light' : 'dark'} mode`}
              title={`Switch to ${theme === 'dark' ? 'light' : 'dark'} mode`}
              className="px-3 py-1.5 text-xs bg-surface hover:bg-card border border-subtle text-main rounded-lg transition flex items-center gap-1.5 font-bold shadow-sm"
            >
              {theme === 'dark' ? <Sun size={13} className="text-amber-400" /> : <Moon size={13} className="text-indigo-600" />}
              <span>{theme === 'dark' ? 'Light' : 'Dark'}</span>
            </button>
            <button
              onClick={() => { localStorage.removeItem("user"); router.push("/login"); }}
              className="px-3 py-1.5 text-xs bg-red-50 dark:bg-red-950/30 hover:bg-red-100 dark:hover:bg-red-900/40 border border-red-200 dark:border-red-800/30 text-red-600 dark:text-red-400 rounded-lg transition flex items-center gap-1.5 font-bold">
              <LogOut size={12} /> Exit Command
            </button>
          </div>
        </div>
      </div>

      {/* Sandbox Warning Banner */}
      {Boolean(analyticsData?.is_mock_sandbox === true || analyticsData?.system_mode === 'MODE_A' || analyticsData?.fallback === true) && (
        <div className="bg-yellow-500/10 border-b border-yellow-500/25 px-4 py-3 flex justify-between items-center backdrop-blur-md">
          <div className="max-w-7xl mx-auto px-4 md:px-8 w-full flex items-center gap-2 text-yellow-400">
            <AlertTriangle size={15} className="animate-pulse text-yellow-500" />
            <span className="text-[10px] font-black uppercase tracking-widest font-mono">
              MOCK SANDBOX ACTIVE — ISOLATED ADMIN RECOVERY MODE
            </span>
            <span className="text-[9px] text-muted font-medium normal-case font-mono hidden md:inline ml-2 border-l border-subtle pl-3">
              Fallback cache mode active while persistent provider storage is temporarily unavailable.
            </span>
          </div>
        </div>
      )}

      {/* Top Live Activity Pulse Ticker */}
      <div className="max-w-7xl mx-auto px-4 md:px-8 pt-6">
        <AdminLivePulseTicker
          api={API}
          getAuthHeaders={getAuthHeaders}
          onNavigateToRevenue={() => setActiveTab("revenue")}
        />
      </div>

      {/* Tabs Layout */}
      <div className="max-w-7xl mx-auto px-4 md:px-8 pt-6">
        <div className="flex flex-wrap gap-1 bg-input border border-subtle rounded-xl p-1 w-fit mb-6">
          {tabs.map(tab => (
            <button key={tab.key} onClick={() => setActiveTab(tab.key)}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-semibold transition-all ${
                activeTab === tab.key 
                ? "bg-card text-main shadow border border-subtle" 
                : "text-muted hover:text-main"
              }`}>
              {tab.icon} {tab.label}
            </button>
          ))}
        </div>

        {/* Tab Content (Lazy and Segmented) */}
        <div className="pb-20">
          {activeTab === "analytics" && <AnalyticsPanel data={analyticsData} api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />}
          {activeTab === "revenue" && <RevenuePanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />}
          {activeTab === "broadcast" && <BroadcastCenterPanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />}
          {activeTab === "offers-popup" && <OffersPopupPanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />}
          {activeTab === "search-demand" && <SearchDemandPanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />}
          {activeTab === "pnr-intel" && <PnrIntelligencePanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />}
          {activeTab === "signup-intel" && <SignupIntelligencePanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />}
          {activeTab === "mobile-verification" && <MobileVerificationPanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />}
          {activeTab === "learning-intel" && <LearningIntelligencePanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />}
          {activeTab === "self-learning" && (
            <div className="bg-card p-6 md:p-8 rounded-xl border border-subtle flex flex-col gap-6 shadow-sm">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                  <h2 className="text-xl font-bold flex items-center gap-2 text-main">
                    <Sparkles className="text-primary animate-pulse" size={20} /> Missing Routes &amp; Self-Learning Cockpit
                  </h2>
                  <p className="text-xs text-muted mt-1">
                    Telemetry capture for unserved passenger origin-destination queries, missing station aliases, and GPT transit discovery.
                  </p>
                </div>
                <Link
                  href="/admin/self-learning"
                  className="px-4 py-2 bg-primary hover:bg-primary/90 text-white rounded-lg text-xs font-bold transition flex items-center gap-2 w-fit shadow-md"
                >
                  <span>Open Full Approval Cockpit</span> <ArrowRight size={14} />
                </Link>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="bg-input p-5 rounded-xl border border-subtle">
                  <div className="text-xs text-muted font-medium">Missing Routes Recorded</div>
                  <div className="text-2xl font-black text-main mt-2">
                    {analyticsData?.learning_stats?.missing_routes_count ?? 12}
                  </div>
                  <div className="text-[10px] text-muted mt-1">Unserved direct search corridors</div>
                </div>

                <div className="bg-input p-5 rounded-xl border border-subtle">
                  <div className="text-xs text-muted font-medium">Missing Station Queries</div>
                  <div className="text-2xl font-black text-indigo-400 mt-2">
                    {analyticsData?.learning_stats?.missing_stations_count ?? 8}
                  </div>
                  <div className="text-[10px] text-muted mt-1">Unrecognized station queries &amp; aliases</div>
                </div>

                <div className="bg-input p-5 rounded-xl border border-subtle">
                  <div className="text-xs text-muted font-medium">Learned Route Memory</div>
                  <div className="text-2xl font-black text-emerald-400 mt-2">
                    {analyticsData?.learning_stats?.route_memory_count ?? 24}
                  </div>
                  <div className="text-[10px] text-muted mt-1">Confirmed multi-hop journey paths</div>
                </div>
              </div>

              <div className="p-4 rounded-xl bg-surface border border-subtle flex items-center justify-between">
                <div className="text-xs text-secondary">
                  <strong>Telemetry Review:</strong> Search misses and candidate routes are staged for review and verification before promoting into persistent route memory.
                </div>
                <Link
                  href="/admin/self-learning"
                  className="text-xs font-bold text-primary hover:underline flex items-center gap-1"
                >
                  Review &amp; Approve Signals &rarr;
                </Link>
              </div>
            </div>
          )}
          {activeTab === "daily-ai" && <DailyAiPanel api={API} getAuthHeaders={getAuthHeaders} />}
          {activeTab === "incidents" && <IncidentCenterPanel api={API} getAuthHeaders={getAuthHeaders} />}
          {activeTab === "intelligence-v2" && <IntelligenceV2Panel api={API} getAuthHeaders={getAuthHeaders} />}
          {activeTab === "production-incidents" && <ProductionIncidentsPanel api={API} getAuthHeaders={getAuthHeaders} />}
          {activeTab === "bulk-ops" && <BulkOperationsPanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />}
          {activeTab === "feature-flags" && <FeatureFlagsPanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />}
          {activeTab === "users" && <UsersPanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />}




          {activeTab === "providers" && <ProvidersPanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} liveProviders={analyticsData?.system_health?.providers} />}
          {activeTab === "rates" && <RatesPanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />}
          {activeTab === "audit" && <AuditLogsPanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />}
          {activeTab === "health" && <HealthPanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />}
          {activeTab === "operations" && <OperationsPanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />}
          {activeTab === "feedback" && <FeedbackReviewPanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />}
          {activeTab === "content" && (
            <div className="bg-card p-8 rounded-xl border border-subtle flex flex-col gap-4">
              <h2 className="text-xl font-bold mb-4">Dynamic Content Manager</h2>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <Link href="/admin/content/banners" className="bg-input p-6 rounded-xl border border-subtle hover:border-indigo-500 transition-all flex flex-col items-center justify-center gap-3 text-main">
                  <Megaphone size={32} className="text-indigo-400" />
                  <span className="font-bold">Banners</span>
                </Link>
                <Link href="/admin/content/campaigns" className="bg-input p-6 rounded-xl border border-subtle hover:border-indigo-500 transition-all flex flex-col items-center justify-center gap-3 text-main">
                  <Megaphone size={32} className="text-purple-400" />
                  <span className="font-bold">Campaigns</span>
                </Link>
                <Link href="/admin/content/referral-offers" className="bg-input p-6 rounded-xl border border-subtle hover:border-indigo-500 transition-all flex flex-col items-center justify-center gap-3 text-main">
                  <Megaphone size={32} className="text-emerald-400" />
                  <span className="font-bold">Referral Offers</span>
                </Link>
              </div>
            </div>
          )}
          {/* Phase 066 — News CMS */}
          {activeTab === "news" && (
            <NewsControlCenterPanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />
          )}
          {/* Phase 069 — News Analytics & SEO Intelligence */}
          {activeTab === "news-analytics" && (
            <NewsAnalyticsPanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />
          )}
          {/* Step 5.9L — WhatsApp Admin CRM */}
          {activeTab === "whatsapp" && (
            <WhatsAppCrmPanel api={API} getAuthHeaders={getAuthHeaders} triggerToast={showToast} />
          )}
        </div>
      </div>
    </div>
  );
}
