"use client";

import React, { useEffect, useState, useCallback } from "react";
import { 
  Banknote, RefreshCw, CheckCircle2, XCircle, Clock, 
  Search, ArrowUpRight, TrendingUp, ShieldAlert, Filter, ChevronLeft, ChevronRight
} from "lucide-react";
import { fetchWithAuth } from "@/lib/fetchWithAuth";

interface RevenuePanelProps {
  api: string;
  getAuthHeaders: () => Record<string, string>;
  triggerToast: (msg: string, type: "success" | "error" | "info") => void;
}

const PLAN_MAP: Record<string, string> = {
  safar_pro_30m: "Blitz PRO (30 Min)",
  safar_pro_1d: "1-Day AI Pass",
  safar_pro_7d: "7-Day AI Pass",
  safar_pro_30d: "Pro Monthly (30 Days)",
  safar_pro_90d: "Pro Yearly (365 Days)",
  safar_pro: "Legacy Safar Pro",
};

export function RevenuePanel({ api, getAuthHeaders, triggerToast }: RevenuePanelProps) {
  const [revenueStats, setRevenueStats] = useState<{ total: number; today: number; month: number }>({ total: 0, today: 0, month: 0 });
  const [metrics, setMetrics] = useState<{ successful: number; failed: number; topPlans: Array<{ plan_id: string; count: number }> }>({ successful: 0, failed: 0, topPlans: [] });
  const [transactions, setTransactions] = useState<any[]>([]);
  const [totalCount, setTotalCount] = useState<number>(0);
  const [page, setPage] = useState<number>(1);
  const [statusFilter, setStatusFilter] = useState<string>("ALL");
  const [searchTerm, setSearchTerm] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(true);

  const fetchRevenueData = useCallback(async () => {
    try {
      setLoading(true);
      const headers = getAuthHeaders();

      const [revRes, metRes, txRes] = await Promise.all([
        fetchWithAuth(`${api}/api/admin/revenue`, { headers }),
        fetchWithAuth(`${api}/api/admin/payment-metrics`, { headers }),
        fetchWithAuth(`${api}/api/admin/transactions?page=${page}&limit=15&status=${statusFilter}`, { headers })
      ]);

      if (revRes.ok) {
        const json = await revRes.json();
        if (json.success) setRevenueStats(json.data);
      }

      if (metRes.ok) {
        const json = await metRes.json();
        if (json.success) setMetrics(json.data);
      }

      if (txRes.ok) {
        const json = await txRes.json();
        if (json.success) {
          setTransactions(json.data.transactions || []);
          setTotalCount(json.data.total || 0);
        }
      }
    } catch (err: any) {
      console.error("[REVENUE_FETCH_ERROR]", err);
      triggerToast("Failed to fetch revenue analytics", "error");
    } finally {
      setLoading(false);
    }
  }, [api, page, statusFilter, getAuthHeaders, triggerToast]);

  useEffect(() => {
    fetchRevenueData();
  }, [fetchRevenueData]);

  const filteredTransactions = transactions.filter((tx) => {
    if (!searchTerm) return true;
    const term = searchTerm.toLowerCase();
    return (
      tx.user_name?.toLowerCase().includes(term) ||
      tx.user_email?.toLowerCase().includes(term) ||
      tx.user_phone?.includes(term) ||
      tx.order_id?.toLowerCase().includes(term) ||
      tx.plan_id?.toLowerCase().includes(term)
    );
  });

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-subtle pb-4">
        <div>
          <h2 className="text-xl font-bold flex items-center gap-2 text-main">
            <Banknote className="text-emerald-500" size={22} />
            Revenue &amp; Subscriptions Command
          </h2>
          <p className="text-xs text-muted mt-0.5">
            Real-time monetization telemetry, subscription ledger, payment conversions &amp; plan distribution.
          </p>
        </div>
        <button
          onClick={fetchRevenueData}
          disabled={loading}
          className="px-3.5 py-2 rounded-xl bg-surface hover:bg-input border border-subtle text-secondary hover:text-main text-xs font-semibold transition flex items-center gap-2 shadow-sm w-fit"
        >
          <RefreshCw size={13} className={loading ? "animate-spin text-primary" : ""} />
          <span>Refresh Data</span>
        </button>
      </div>

      {/* KPI Cards Row */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {/* Card 1: Today's Revenue */}
        <div className="p-5 rounded-2xl bg-gradient-to-br from-emerald-500/15 via-card to-card border border-emerald-500/25 shadow-sm relative overflow-hidden">
          <div className="flex items-center justify-between text-xs text-muted mb-1 font-semibold uppercase tracking-wider">
            <span className="text-emerald-500">Today&apos;s Revenue</span>
            <span className="px-2 py-0.5 rounded-full text-[9px] font-bold bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 font-mono">LIVE</span>
          </div>
          <div className="text-3xl font-black text-main font-mono mt-2">
            ₹{revenueStats.today.toLocaleString()}
          </div>
          <div className="text-xs text-secondary mt-1 flex items-center gap-1 font-medium">
            <TrendingUp size={13} className="text-emerald-500" /> Realized booking conversions
          </div>
        </div>

        {/* Card 2: This Month's Revenue */}
        <div className="p-5 rounded-2xl bg-card border border-subtle shadow-sm">
          <div className="text-xs text-muted font-semibold uppercase tracking-wider">
            This Month (MTD)
          </div>
          <div className="text-3xl font-black text-main font-mono mt-2">
            ₹{revenueStats.month.toLocaleString()}
          </div>
          <div className="text-xs text-muted mt-1">Calendar month earnings</div>
        </div>

        {/* Card 3: Total Lifetime Revenue */}
        <div className="p-5 rounded-2xl bg-card border border-subtle shadow-sm">
          <div className="text-xs text-muted font-semibold uppercase tracking-wider">
            Total Revenue
          </div>
          <div className="text-3xl font-black text-main font-mono mt-2 text-indigo-400">
            ₹{revenueStats.total.toLocaleString()}
          </div>
          <div className="text-xs text-muted mt-1">Platform gross volume</div>
        </div>

        {/* Card 4: Success vs Failed Transactions */}
        <div className="p-5 rounded-2xl bg-card border border-subtle shadow-sm">
          <div className="text-xs text-muted font-semibold uppercase tracking-wider">
            Gateway Health
          </div>
          <div className="flex items-baseline gap-2 mt-2">
            <span className="text-2xl font-black text-emerald-500 font-mono">{metrics.successful}</span>
            <span className="text-xs text-muted">Success</span>
            <span className="text-muted">/</span>
            <span className="text-2xl font-black text-rose-500 font-mono">{metrics.failed}</span>
            <span className="text-xs text-muted">Failed</span>
          </div>
          <div className="text-xs text-muted mt-1">
            Conversion rate: {metrics.successful + metrics.failed > 0 ? `${((metrics.successful / (metrics.successful + metrics.failed)) * 100).toFixed(1)}%` : "100%"}
          </div>
        </div>
      </div>

      {/* Top Plans Breakdown Bar */}
      {metrics.topPlans && metrics.topPlans.length > 0 && (
        <div className="p-4 rounded-2xl bg-card border border-subtle shadow-sm">
          <div className="text-xs font-bold uppercase tracking-wider text-muted mb-3">
            Top Performing Subscription Plans
          </div>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            {metrics.topPlans.map((tp) => (
              <div key={tp.plan_id} className="p-3 rounded-xl bg-surface border border-subtle">
                <div className="text-xs font-semibold text-main truncate">
                  {PLAN_MAP[tp.plan_id] || tp.plan_id}
                </div>
                <div className="text-lg font-black font-mono text-primary mt-1">
                  {tp.count} <span className="text-xs font-normal text-muted">sold</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Transactions Table Section */}
      <div className="bg-card rounded-2xl border border-subtle shadow-sm overflow-hidden">
        {/* Table Controls */}
        <div className="p-4 border-b border-subtle flex flex-col sm:flex-row sm:items-center justify-between gap-3 bg-surface/50">
          <div className="flex items-center gap-2 flex-1 max-w-md">
            <div className="relative w-full">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted" size={14} />
              <input
                type="text"
                placeholder="Search user, email, phone, or order ID..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-9 pr-3 py-1.5 bg-input border border-subtle rounded-xl text-xs text-main focus:outline-none focus:border-strong transition"
              />
            </div>
          </div>

          <div className="flex items-center gap-2">
            <span className="text-xs text-muted font-medium flex items-center gap-1">
              <Filter size={12} /> Status:
            </span>
            {(["ALL", "SUCCESS", "FAILED", "PENDING"] as const).map((st) => (
              <button
                key={st}
                onClick={() => { setStatusFilter(st); setPage(1); }}
                className={`px-3 py-1 rounded-lg text-xs font-bold transition ${
                  statusFilter === st
                    ? "bg-primary text-white shadow-sm"
                    : "bg-surface border border-subtle text-muted hover:text-main"
                }`}
              >
                {st}
              </button>
            ))}
          </div>
        </div>

        {/* Table Content */}
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead>
              <tr className="border-b border-subtle bg-surface/80 text-muted uppercase font-bold text-[10px] tracking-wider">
                <th className="py-3 px-4">Passenger / User</th>
                <th className="py-3 px-4">Plan</th>
                <th className="py-3 px-4">Amount</th>
                <th className="py-3 px-4">Gateway</th>
                <th className="py-3 px-4">Status</th>
                <th className="py-3 px-4">Date &amp; Time</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-subtle font-medium">
              {filteredTransactions.map((tx) => (
                <tr key={tx.id || tx.order_id} className="hover:bg-surface/50 transition">
                  <td className="py-3 px-4">
                    <div className="font-bold text-main">{tx.user_name}</div>
                    <div className="text-[11px] text-muted font-mono">{tx.user_email !== "N/A" ? tx.user_email : (tx.user_phone !== "N/A" ? tx.user_phone : tx.user_id?.slice(0, 10))}</div>
                  </td>
                  <td className="py-3 px-4">
                    <span className="px-2.5 py-1 rounded-lg bg-surface border border-subtle font-semibold text-main">
                      {PLAN_MAP[tx.plan_id] || tx.plan_id || "Pro Pass"}
                    </span>
                  </td>
                  <td className="py-3 px-4 font-mono font-black text-main text-sm">
                    ₹{tx.amount}
                  </td>
                  <td className="py-3 px-4 uppercase text-[11px] font-mono text-muted">
                    {tx.provider || "Razorpay"}
                  </td>
                  <td className="py-3 px-4">
                    {tx.status === "SUCCESS" && (
                      <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20 text-[10px] font-bold">
                        <CheckCircle2 size={11} /> SUCCESS
                      </span>
                    )}
                    {tx.status === "FAILED" && (
                      <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full bg-rose-500/10 text-rose-600 dark:text-rose-400 border border-rose-500/20 text-[10px] font-bold">
                        <XCircle size={11} /> FAILED
                      </span>
                    )}
                    {tx.status === "PENDING" && (
                      <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full bg-amber-500/10 text-amber-600 dark:text-amber-400 border border-amber-500/20 text-[10px] font-bold">
                        <Clock size={11} /> PENDING
                      </span>
                    )}
                  </td>
                  <td className="py-3 px-4 text-muted font-mono text-[11px]">
                    {new Date(tx.created_at).toLocaleString("en-IN", {
                      month: "short",
                      day: "numeric",
                      hour: "2-digit",
                      minute: "2-digit"
                    })}
                  </td>
                </tr>
              ))}

              {filteredTransactions.length === 0 && !loading && (
                <tr>
                  <td colSpan={6} className="py-12 text-center text-muted">
                    No transactions found for the selected criteria.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* Pagination Footer */}
        <div className="p-3 border-t border-subtle flex items-center justify-between text-xs text-muted bg-surface/30">
          <div>
            Showing {filteredTransactions.length} of {totalCount} transactions
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setPage((p) => Math.max(1, p - 1))}
              disabled={page <= 1}
              className="p-1.5 rounded-lg bg-surface hover:bg-input border border-subtle disabled:opacity-40 transition"
            >
              <ChevronLeft size={14} />
            </button>
            <span className="font-mono font-bold text-main px-2">Page {page}</span>
            <button
              onClick={() => setPage((p) => p + 1)}
              disabled={filteredTransactions.length < 15}
              className="p-1.5 rounded-lg bg-surface hover:bg-input border border-subtle disabled:opacity-40 transition"
            >
              <ChevronRight size={14} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
