"use client";

import React, { useEffect, useState, useCallback } from "react";
import { 
  Ticket, Activity, CheckCircle2, AlertCircle, Clock, 
  RefreshCw, TrendingUp, ShieldCheck, ArrowRight, Sparkles, Filter,
  Eye, EyeOff, Copy, Check
} from "lucide-react";
import { fetchWithAuth } from "@/lib/fetchWithAuth";
import { WaitlistFunnelCard } from "./WaitlistFunnelCard";

interface PnrIntelligencePanelProps {
  api: string;
  getAuthHeaders: () => Record<string, string>;
  triggerToast: (msg: string, type: "success" | "error" | "info") => void;
}

export function PnrIntelligencePanel({ api, getAuthHeaders, triggerToast }: PnrIntelligencePanelProps) {
  const [data, setData] = useState<{
    recentPnrChecks: any[];
    statusBreakdown: { confirmed: number; waitlist: number; rac: number; total: number };
    topWaitlistedTrains: any[];
  }>({
    recentPnrChecks: [],
    statusBreakdown: { confirmed: 0, waitlist: 0, rac: 0, total: 0 },
    topWaitlistedTrains: []
  });

  const [loading, setLoading] = useState<boolean>(true);
  const [statusFilter, setStatusFilter] = useState<"ALL" | "WL" | "CNF">("ALL");
  const [unmaskedPnrs, setUnmaskedPnrs] = useState<Record<string, boolean>>({});
  const [copiedPnr, setCopiedPnr] = useState<string | null>(null);

  const toggleUnmask = (key: string) => {
    setUnmaskedPnrs(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const copyToClipboard = (text: string) => {
    if (!text) return;
    navigator.clipboard.writeText(text);
    setCopiedPnr(text);
    triggerToast("PNR copied to clipboard", "success");
    setTimeout(() => setCopiedPnr(null), 2000);
  };

  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      const res = await fetchWithAuth(`${api}/api/admin/pnr-intelligence`, {
        headers: getAuthHeaders()
      });
      if (res.ok) {
        const json = await res.json();
        if (json.success && json.data) {
          setData(json.data);
        }
      }
    } catch (err: any) {
      triggerToast("Failed to fetch PNR intelligence", "error");
    } finally {
      setLoading(false);
    }
  }, [api, getAuthHeaders, triggerToast]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const filteredPnrList = data.recentPnrChecks.filter((p) => {
    if (statusFilter === "ALL") return true;
    const st = (p.current_status || p.booking_status || "").toUpperCase();
    if (statusFilter === "WL") return st.includes("WL") || st.includes("WAIT");
    if (statusFilter === "CNF") return st.includes("CNF") || st.includes("CONFIRM");
    return true;
  });

  const cnfRate = data.statusBreakdown.total > 0 
    ? Math.round((data.statusBreakdown.confirmed / data.statusBreakdown.total) * 100) 
    : 72;
  const wlRate = data.statusBreakdown.total > 0 
    ? Math.round((data.statusBreakdown.waitlist / data.statusBreakdown.total) * 100) 
    : 20;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-subtle pb-4">
        <div>
          <h2 className="text-xl font-bold flex items-center gap-2 text-main">
            <Ticket className="text-sky-500" size={22} />
            PNR Passenger Intelligence &amp; Watchlist
          </h2>
          <p className="text-xs text-muted mt-0.5">
            Monitor real-time passenger booking statuses, waitlist ratios, AI confirmation predictions &amp; distressed routes.
          </p>
        </div>
        <button
          onClick={fetchData}
          disabled={loading}
          className="px-3.5 py-2 rounded-xl bg-surface hover:bg-input border border-subtle text-secondary hover:text-main text-xs font-semibold transition flex items-center gap-2 shadow-sm w-fit"
        >
          <RefreshCw size={13} className={loading ? "animate-spin text-primary" : ""} />
          <span>Refresh Watchlist</span>
        </button>
      </div>

      {/* KPI Bento Row */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="p-5 rounded-2xl bg-card border border-subtle shadow-sm">
          <div className="flex items-center justify-between text-xs text-muted mb-1 font-semibold uppercase tracking-wider">
            <span>Recent PNR Validations</span>
            <Activity size={14} className="text-sky-500" />
          </div>
          <div className="text-3xl font-black text-main font-mono mt-2">
            {data.statusBreakdown.total || data.recentPnrChecks.length}
          </div>
          <div className="text-xs text-muted mt-1">Passenger journeys verified</div>
        </div>

        <div className="p-5 rounded-2xl bg-card border border-subtle shadow-sm">
          <div className="flex items-center justify-between text-xs text-muted mb-1 font-semibold uppercase tracking-wider">
            <span>Confirmation Ratio</span>
            <CheckCircle2 size={14} className="text-emerald-500" />
          </div>
          <div className="text-3xl font-black text-emerald-500 font-mono mt-2">
            {cnfRate}% <span className="text-xs font-normal text-muted font-sans">Confirmed</span>
          </div>
          <div className="w-full bg-surface h-2 rounded-full mt-2 overflow-hidden flex">
            <div style={{ width: `${cnfRate}%` }} className="bg-emerald-500 h-full" />
            <div style={{ width: `${wlRate}%` }} className="bg-amber-500 h-full" />
          </div>
        </div>

        <div className="p-5 rounded-2xl bg-gradient-to-br from-amber-500/10 via-card to-card border border-amber-500/25 shadow-sm">
          <div className="flex items-center justify-between text-xs text-muted mb-1 font-semibold uppercase tracking-wider">
            <span className="text-amber-500">Waitlisted Passengers</span>
            <AlertCircle size={14} className="text-amber-500" />
          </div>
          <div className="text-3xl font-black text-amber-500 font-mono mt-2">
            {data.statusBreakdown.waitlist}
          </div>
          <div className="text-xs text-secondary mt-1">Prime candidates for confirmed split journey conversion</div>
        </div>
      </div>

      {/* Live Waitlist Next-Action Funnel Analytics Widget */}
      <WaitlistFunnelCard api={api} getAuthHeaders={getAuthHeaders} triggerToast={triggerToast} />

      {/* Top Waitlisted Trains Callout */}
      {data.topWaitlistedTrains && data.topWaitlistedTrains.length > 0 && (
        <div className="p-4 rounded-2xl bg-card border border-subtle shadow-sm">
          <div className="text-xs font-bold uppercase tracking-wider text-muted mb-3 flex items-center gap-1.5">
            <AlertCircle size={14} className="text-amber-500" />
            Highest Waitlist Train Services (High Booking Distress)
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            {data.topWaitlistedTrains.map((tr) => (
              <div key={tr.train_no} className="p-3 rounded-xl bg-surface border border-subtle flex items-center justify-between">
                <div>
                  <div className="text-xs font-bold text-main">{tr.train_no} - {tr.train_name}</div>
                  <div className="text-[10px] text-muted">Severe seat crunch reported</div>
                </div>
                <span className="px-2 py-0.5 rounded font-mono text-xs font-black bg-amber-500/15 text-amber-500 border border-amber-500/30">
                  {tr.waitlist_checks} WL
                </span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* PNR History Table */}
      <div className="bg-card rounded-2xl border border-subtle shadow-sm overflow-hidden">
        <div className="p-4 border-b border-subtle flex items-center justify-between bg-surface/50">
          <div className="text-xs font-bold uppercase tracking-wider text-main flex items-center gap-2">
            <Ticket size={14} className="text-sky-500" /> Live Passenger PNR Stream
          </div>

          <div className="flex items-center gap-1 bg-surface p-1 rounded-lg border border-subtle">
            {(["ALL", "WL", "CNF"] as const).map((mode) => (
              <button
                key={mode}
                onClick={() => setStatusFilter(mode)}
                className={`px-3 py-1 rounded-md text-[11px] font-bold transition ${
                  statusFilter === mode
                    ? "bg-primary text-white shadow-sm"
                    : "text-muted hover:text-main"
                }`}
              >
                {mode === "ALL" ? "All Status" : mode === "WL" ? "Waitlist Only" : "Confirmed Only"}
              </button>
            ))}
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead>
              <tr className="border-b border-subtle bg-surface/80 text-muted uppercase font-bold text-[10px] tracking-wider">
                <th className="py-3 px-4">Masked PNR</th>
                <th className="py-3 px-4">Train Service</th>
                <th className="py-3 px-4">Corridor</th>
                <th className="py-3 px-4">Class</th>
                <th className="py-3 px-4">Current Status</th>
                <th className="py-3 px-4">AI Prediction</th>
                <th className="py-3 px-4">Checked At</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-subtle font-medium">
              {filteredPnrList.map((p, idx) => {
                const isWl = (p.current_status || p.booking_status || "").toUpperCase().includes("WL");
                const isCnf = (p.current_status || p.booking_status || "").toUpperCase().includes("CNF");

                return (
                  <tr key={idx} className="hover:bg-surface/50 transition">
                    <td className="py-3 px-4 font-mono font-bold text-main">
                      <div className="flex items-center gap-1.5">
                        <span className="tracking-wide">
                          {unmaskedPnrs[p.full_pnr || p.pnr || idx] && (p.full_pnr || p.pnr)
                            ? (p.full_pnr || p.pnr)
                            : p.pnr}
                        </span>
                        {(p.full_pnr || p.pnr) && (
                          <div className="flex items-center gap-1">
                            <button
                              type="button"
                              onClick={() => toggleUnmask(p.full_pnr || p.pnr || idx)}
                              title={unmaskedPnrs[p.full_pnr || p.pnr || idx] ? "Mask PNR" : "Unmask full 10-digit PNR"}
                              className="p-1 rounded hover:bg-input text-muted hover:text-sky-400 transition cursor-pointer"
                            >
                              {unmaskedPnrs[p.full_pnr || p.pnr || idx] ? <EyeOff size={13} /> : <Eye size={13} />}
                            </button>
                            <button
                              type="button"
                              onClick={() => copyToClipboard(p.full_pnr || p.pnr)}
                              title="Copy PNR"
                              className="p-1 rounded hover:bg-input text-muted hover:text-sky-400 transition cursor-pointer"
                            >
                              {copiedPnr === (p.full_pnr || p.pnr) ? (
                                <Check size={13} className="text-emerald-400" />
                              ) : (
                                <Copy size={13} />
                              )}
                            </button>
                          </div>
                        )}
                      </div>
                    </td>
                    <td className="py-3 px-4 font-semibold text-main">
                      {p.train_no} <span className="text-muted font-normal text-[11px]">({p.train_name})</span>
                    </td>
                    <td className="py-3 px-4 text-main">
                      {p.source} &rarr; {p.destination}
                    </td>
                    <td className="py-3 px-4 font-mono uppercase text-muted font-bold">
                      {p.class || "3A"}
                    </td>
                    <td className="py-3 px-4">
                      {isCnf ? (
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20 text-[10px] font-bold">
                          <CheckCircle2 size={11} /> {p.current_status || "CNF"}
                        </span>
                      ) : isWl ? (
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-amber-500/10 text-amber-500 border border-amber-500/20 text-[10px] font-bold">
                          <AlertCircle size={11} /> {p.current_status || "WL"}
                        </span>
                      ) : (
                        <span className="px-2 py-0.5 rounded-full bg-surface border border-subtle text-muted text-[10px]">
                          {p.current_status || "UNKNOWN"}
                        </span>
                      )}
                    </td>
                    <td className="py-3 px-4 font-mono font-bold text-primary text-[11px]">
                      {p.prediction_chance || "—"}
                    </td>
                    <td className="py-3 px-4 text-muted font-mono text-[11px]">
                      {p.checked_at ? new Date(p.checked_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : "Recently"}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
